import 'package:flutter/material.dart';

import '../../../../route_generator.dart';
import 'unlock_wallet_keys_desktop.dart';

/// Ask for the password, then show the keys of a wallet.
Future<void> showWalletKeys(BuildContext context, String walletId) =>
    showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (context) => Navigator(
        initialRoute: UnlockWalletKeysDesktop.routeName,
        onGenerateRoute: RouteGenerator.generateRoute,
        onGenerateInitialRoutes: (_, _) {
          return [
            RouteGenerator.generateRoute(
              RouteSettings(
                name: UnlockWalletKeysDesktop.routeName,
                arguments: walletId,
              ),
            ),
          ];
        },
      ),
    );
